const items = $input.all();

const uniqueAds = [];
const seenIds = new Set();

function getText(value) {
  if (typeof value === 'string') return value.trim();
  if (typeof value === 'number') return String(value);
  return '';
}

function firstText(...values) {
  for (const value of values) {
    const text = getText(value);
    if (text) return text;
  }
  return '';
}

function uniqueTexts(values) {
  const seen = new Set();

  return values.filter(value => {
    const text = getText(value);
    if (!text) return false;

    const key = text.toLowerCase();
    if (seen.has(key)) return false;

    seen.add(key);
    return true;
  });
}

function getMedia(ad) {
  const snapshot = ad.snapshot || {};
  const cards = Array.isArray(snapshot.cards) ? snapshot.cards : [];

  const imageUrls = new Set();
  const videoUrls = new Set();

  function addUrl(set, value) {
    if (
      typeof value === 'string' &&
      /^https?:\/\//i.test(value.trim())
    ) {
      set.add(value.trim());
    }
  }

  // Extract media URLs from the ad and its snapshot
  for (const obj of [ad, snapshot]) {
    // Image URLs
    addUrl(imageUrls, obj.originalImageUrl);
    addUrl(imageUrls, obj.resizedImageUrl);
    addUrl(imageUrls, obj.imageUrl);
    addUrl(imageUrls, obj.image_url);
    addUrl(imageUrls, obj.thumbnailUrl);
    addUrl(imageUrls, obj.thumbnail_url);

    // Video preview image / thumbnail
    addUrl(imageUrls, obj.videoPreviewImageUrl);

    // Video file URLs
    addUrl(videoUrls, obj.videoUrl);
    addUrl(videoUrls, obj.video_url);
    addUrl(videoUrls, obj.videoHdUrl);
    addUrl(videoUrls, obj.videoSdUrl);
  }

  // Extract media URLs from carousel cards
  for (const card of cards) {
    addUrl(imageUrls, card.originalImageUrl);
    addUrl(imageUrls, card.resizedImageUrl);
    addUrl(imageUrls, card.imageUrl);
    addUrl(imageUrls, card.image_url);
    addUrl(imageUrls, card.thumbnailUrl);
    addUrl(imageUrls, card.videoPreviewImageUrl);

    addUrl(videoUrls, card.videoUrl);
    addUrl(videoUrls, card.video_url);
    addUrl(videoUrls, card.videoHdUrl);
    addUrl(videoUrls, card.videoSdUrl);
  }

  return {
    image_urls: [...imageUrls],
    video_urls: [...videoUrls],
  };
}

for (const item of items) {
  const ad = item.json;
  const archiveId = firstText(ad.adArchiveID, ad.adArchiveId);

  // Remove duplicate ads when a reliable ad ID is available
  if (archiveId) {
    if (seenIds.has(archiveId)) continue;
    seenIds.add(archiveId);
  }

  const snapshot = ad.snapshot || {};
  const cards = Array.isArray(snapshot.cards) ? snapshot.cards : [];

  const title = firstText(
    snapshot.title,
    ad.title,
    ...cards.map(card => card.title)
  );

  const body = firstText(
    snapshot.body?.text,
    snapshot.body,
    ad.body,
    ad.adText,
    ...cards.map(card => card.body)
  );

  const cta = firstText(
    snapshot.ctaText,
    snapshot.callToAction,
    ad.ctaText,
    ad.callToAction,
    ...cards.map(card => card.ctaText)
  );

  const cardText = uniqueTexts(
    cards.map(card =>
      [
        card.title,
        card.body,
        card.linkDescription,
        card.caption,
      ]
        .map(getText)
        .filter(Boolean)
        .join('\n')
        .trim()
    )
  );

  // Remove repeated title, body and card text
  const textParts = uniqueTexts([
    title,
    body,
    ...cardText,
  ]);

  const cleanedText = [
    ...textParts,
    ...(cta ? [`CTA: ${cta}`] : []),
  ]
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  // Calculate how long the ad has been running
  const rawStartDate = Number(ad.startDate);

  const validStartDate =
    Number.isFinite(rawStartDate) &&
    rawStartDate > 0;

  const daysRunning = validStartDate
    ? Math.max(
        0,
        Math.floor(
          (Date.now() / 1000 - rawStartDate) / 86400
        )
      )
    : null;

  const media = getMedia(ad);

  uniqueAds.push({
    json: {
      ...ad,

      adArchiveID: archiveId || null,
      collationId: ad.collationId || null,
      pageName: firstText(ad.pageName, snapshot.pageName),

      startDate: validStartDate ? rawStartDate : null,
      days_running: daysRunning,

      cleaned_ad_text: cleanedText,
      extracted_hook: title || body.slice(0, 150),
      extracted_body: body || cardText.join('\n'),
      extracted_cta: cta,

      // Extracted media URLs
      image_urls: media.image_urls,
      video_urls: media.video_urls,

      has_image: media.image_urls.length > 0,
      has_video: media.video_urls.length > 0,
    },
  });
}

return uniqueAds;

const items = $input.all();

// Retrieve original ad details from the HTTP Request node
const sourceItems = $('Switch').all();

function getAnalysis(item) {
  const data = item.json;

  let result =
    data.content?.parts?.[0]?.text ??
    data.text ??
    data.output ??
    data.response ??
    data;

  if (typeof result === 'string') {
    result = result
      .replace(/^\s*```json\s*/i, '')
      .replace(/^\s*```\s*/i, '')
      .replace(/\s*```\s*$/, '')
      .trim();

    try {
      result = JSON.parse(result);
    } catch {
      throw new Error(
        'Could not parse Gemini JSON for item.'
      );
    }
  }

  if (Array.isArray(result)) {
    result = result[0];
  }

  if (result?.output && typeof result.output === 'object') {
    result = result.output;
  }

  if (!result || typeof result !== 'object') {
    throw new Error('Invalid Gemini analysis.');
  }

  return result;
}

const analyzedAds = items.map((item, index) => {
  const analysis = getAnalysis(item);
  const source = sourceItems[index]?.json ?? {};
  const ad = {
    ...source,
    ...item.json,
  };

  const hookScore = Number(analysis.hook_strength);
  const audienceScore = Number(analysis.audience_relevance);
  const benefitScore = Number(analysis.benefit_clarity);
  const ctaScore = Number(analysis.cta_quality);

  const scores = [
    hookScore,
    audienceScore,
    benefitScore,
    ctaScore,
  ];

  if (
    scores.some(
      score =>
        !Number.isFinite(score) ||
        score < 1 ||
        score > 10
    )
  ) {
    throw new Error(
      `Ad ${index + 1}: Missing or invalid Gemini scores.`
    );
  }

  const totalScore = Number((
    hookScore * 0.30 +
    audienceScore * 0.25 +
    benefitScore * 0.25 +
    ctaScore * 0.20
  ).toFixed(2));

  return {
    ...ad,

    adArchiveID:
      source.adArchiveID ||
      source.adArchiveId ||
      ad.adArchiveID ||
      ad.adArchiveId ||
      '',

    page_name:
      analysis.page_name ||
      source.page_name ||
      source.pageName ||
      source.snapshot?.pageName ||
      ad.page_name ||
      ad.pageName ||
      '',

    extracted_hook:
      analysis.hook || ad.extracted_hook || 'Not available',

    extracted_body:
      analysis.body || ad.extracted_body || 'Not available',

    extracted_cta:
      analysis.cta || ad.extracted_cta || 'Not available',

    visual_summary: analysis.visual_summary || '',
    on_screen_text: analysis.on_screen_text || '',
    spoken_message: analysis.spoken_message || '',

    hook_strength: hookScore,
    audience_relevance: audienceScore,
    benefit_clarity: benefitScore,
    cta_quality: ctaScore,

    total_score: totalScore,
    reasoning: analysis.reasoning || '',

    rank: 0,
    is_winner: false,
    is_top_3: false,
  };
});

// Remove duplicate ad IDs within this run
const seenIds = new Set();

const uniqueAds = analyzedAds.filter(ad => {
  const id = String(ad.adArchiveID || '').trim();

  if (!id) return true;
  if (seenIds.has(id)) return false;

  seenIds.add(id);
  return true;
});

// Sort by weighted score
uniqueAds.sort((a, b) => b.total_score - a.total_score);

// Assign rank and winner status
uniqueAds.forEach((ad, index) => {
  ad.rank = index + 1;
  ad.is_winner = index === 0;
  ad.is_top_3 = index < 3;
});

return uniqueAds.map(ad => ({
  json: ad,
}));

const raw = $json.content?.parts?.[0]?.text ?? $json.text ?? "";
const report = typeof raw === "string" ? JSON.parse(raw) : raw;

const top5 = (report.top_5_leaderboard || [])
  .map(ad =>
    `${ad.rank}. ${ad.hook}\n   CTA: ${ad.cta}\n   Score: ${ad.score}/10\n   Ad ID: ${ad.ad_archive_id}`
  )
  .join("\n\n");

const suggestions = (report.rewrite_suggestions || [])
  .map((s, i) => `${i + 1}. ${s}`)
  .join("\n");

const text = `MYSIVI FACEBOOK ADS ANALYSIS REPORT

1. WINNING AD SUMMARY
${report.winner_summary || "Not available"}

2. WHY IT WON
${report.why_it_won || "Not available"}

3. WINNER SCORE BREAKDOWN
Hook Strength: ${report.winner_score_breakdown?.hook_strength ?? "Not available"}
Audience Relevance: ${report.winner_score_breakdown?.audience_relevance ?? "Not available"}
Benefit Clarity: ${report.winner_score_breakdown?.benefit_clarity ?? "Not available"}
CTA Quality: ${report.winner_score_breakdown?.cta_quality ?? "Not available"}
Total Score: ${report.winner_score_breakdown?.total_score ?? "Not available"}/10
Days Running: ${report.winner_score_breakdown?.days_running ?? "Not available"}
Impression Rank: ${report.winner_score_breakdown?.impression_rank ?? "Not available"}

4. TOP 5 ADS
${top5 || "Not available"}

5. RUNNER-UP COMPARISON
${report.runner_up_comparison || "Not available"}

6. REWRITE SUGGESTIONS
${suggestions || "Not available"}

7. IMPROVED WINNING AD
Hook: ${report.rewritten_ad?.hook || "Not available"}

Body: ${report.rewritten_ad?.body || "Not available"}

CTA: ${report.rewritten_ad?.cta || "Not available"}

NOTE: Scores are AI-estimated creative-quality ratings, not verified sales or conversion results. Unavailable metrics should not be treated as zero.
`;

return [{ json: { report_text: text } }];

const ads = $input.all().map(item => item.json);

return [{
  json: {
    total_ads: ads.length,
    winner: ads.find(ad => ad.is_winner) || ads[0],
    top_5: ads.slice(0, 5),
    runner_ups: ads.slice(1, 3),
    all_ads: ads
  }
}];
